WITH b AS (SELECT x FROM TABLE(hcm.system.raw_query('default', 'project-task-index-v1', '{"size":0,"aggs":{"c":{"composite":{"size":65000,"sources":[{"code":{"terms":{"field":"Data.boundaryHierarchyCode.district"}}},{"product":{"terms":{"field":"Data.productCode"}}},{"mode":{"terms":{"field":"Data.deliveryMode"}}},{"tile":{"geotile_grid":{"field":"Data.geoPoint","precision":12}}}]},"aggs":{"c":{"geo_centroid":{"field":"Data.geoPoint"}}}}},"query":{"term":{"Data.administrationStatus":"ADMINISTRATION_SUCCESS"}}}')) CROSS JOIN UNNEST(CAST(json_extract(result, '$.aggregations.c.buckets') AS array(json))) AS t(x))
SELECT d.region, d.district, d.boundary_code, json_extract_scalar(x, '$.key.product') AS product,
       CASE json_extract_scalar(x, '$.key.product') WHEN 'MR' THEN 'Measles-Rubella (MR)' WHEN 'IPV' THEN 'fIPV' ELSE json_extract_scalar(x, '$.key.product') END AS product_label, CASE json_extract_scalar(x, '$.key.mode') WHEN 'FIXED_POST' THEN 'Fixed post' WHEN 'HOUSE_TO_HOUSE' THEN 'House to house' WHEN 'TRANSIT_POST' THEN 'Transit post' ELSE json_extract_scalar(x, '$.key.mode') END AS delivery_mode,
       CAST(json_extract_scalar(x, '$.c.location.lat') AS double) AS latitude, CAST(json_extract_scalar(x, '$.c.location.lon') AS double) AS longitude, CAST(json_extract_scalar(x, '$.doc_count') AS bigint) AS doses
FROM b JOIN microplan.public.dim_district d ON d.boundary_code = json_extract_scalar(x, '$.key.code')
